const BOOK_MEMBER_DISCOUNT = 0.1;
const DEFAULT_MEMBER_DISCOUNT = 0.05;
const SAVE10_COUPON = "SAVE10";
const SAVE10_AMOUNT = 10;

interface Priceable {
  price: number;
  category?: string;
}

function memberDiscount(category: string | undefined): number {
  return category === "books" ? BOOK_MEMBER_DISCOUNT : DEFAULT_MEMBER_DISCOUNT;
}

function roundToCents(amount: number): number {
  return Math.round(amount * 100) / 100;
}

export function getPrice(product: Priceable, isMember: boolean, coupon?: string): number {
  let price = product.price;
  if (isMember) {
    price *= 1 - memberDiscount(product.category);
  }
  if (coupon === SAVE10_COUPON) {
    price = Math.max(price - SAVE10_AMOUNT, 0);
  }
  return roundToCents(price);
}
EOF
